url":"https://api.github.com/users/tona3922/followers","following_url":"https://api.github.com/users/tona3922/following{/other_user}","gists_url":"https://api.github.com/users/tona3922/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/tona3922","id":78496719,"login":"tona3922","node_id":"MDQ6VXNlcjc4NDk2NzE5","organizations_url":"https://api.github.com/users/tona3922/orgs","received_events_url":"https://api.github.com/users/tona3922/received_events","repos_url":"https://api.github.com/users/tona3922/repos","site_admin":false,"starred_url":"https://api.github.com/users/tona3922/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/tona3922/subscriptions","type":"User","url":"https://api.github.com/users/tona3922","user_view_type":"public"},"comments_url":"https://api.github.com/repos/tona3922/microfrontend-test-app/commits/f6ed98c3febc72abf734798d963d63f7d452fd26/comments","commit":{"author":{"date":"2026-04-21T17:50:34Z","email":"vothaitoan12@gmail.com","name":"tona3922"},"comment_count":0,"committer":{"date":"2026-04-21T17:50:34Z","email":"vothaitoan12@gmail.com","name":"tona3922"},"message":"Extract AuthUser and OAuthProvider to shared @repo/types package\n\nAdds packages/types with AuthUser and OAuthProvider as the single\nsource of truth. Both shell and react-app now import from @repo/types\ninstead of defining duplicate interfaces locally. Root workspaces\nupdated to include packages/*.\n\nCo-Authored-By: Claude Sonnet 4.6 <noreply@anthropic.com>","tree":{"sha":"a245b7a46587e5150ef0457175a8e697f0e747b5","url":"https://api.github.com/repos/tona3922/microfrontend-test-app/git/trees/a245b7a46587e5150ef0457175a8e697f0e747b5"},"url":"https://api.github.com/repos/tona3922/microfrontend-test-app/git/commits/f6ed98c3febc72abf734798d963d63f7d452fd26","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/78496719?v=4","